import React, { useEffect, useState } from 'react';
import axios from 'axios';

const StudentsDashboard = () => {
    const [students, setStudents] = useState([]);

    useEffect(() => {
        // جلب البيانات من الـ Django API الذي جهزناه
        axios.get('http://127.0.0.1:8000/api/students/')
            .then(res => setStudents(res.data))
            .catch(err => console.error("Error fetching students:", err));
    }, []);

    return (
        <div className="bg-gray-100 min-h-screen p-8">
            <h1 className="text-3xl font-bold text-blue-900 mb-6">طلاب مشروع Stag.io</h1>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {students.map(student => (
                    <div key={student.id} className="bg-white rounded-xl shadow-lg p-6 border-l-4 border-blue-500">
                        <h2 className="text-xl font-semibold text-gray-800">طالب رقم: {student.user}</h2>
                        <p className="text-gray-600 mt-2">📍 الولاية: {student.wilaya}</p>
                        <div className="mt-4 flex justify-between items-center">
                            <a href={student.cv} className="text-blue-600 underline text-sm">تحميل السيرة الذاتية</a>
                            <button className="bg-blue-600 text-white px-4 py-2 rounded-lg text-sm hover:bg-blue-700">تواصل</button>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default StudentsDashboard;
